{"implementation":"def solve(case):
    # Validate required top-level keys
    if not isinstance(case, dict):
        raise ValueError("case must be a dict")
    if "threshold" not in case or "calls" not in case:
        raise ValueError("case must contain 'threshold' and 'calls'")
    threshold = case["threshold"]
    if not isinstance(threshold, (int, float)):
        raise ValueError("threshold must be a number")
    calls = case["calls"]
    if not isinstance(calls, list):
        raise ValueError("calls must be a list")
    # Validate each call
    required_call_fields = ["call_id", "loss_without_call", "loss_with_call", "prediction_tokens", "parseable"]
    for c in calls:
        if not isinstance(c, dict):
            raise ValueError("each call must be a dict")
        for field in required_call_fields:
            if field not in c:
                raise ValueError(f"call missing required field '{field}'")
        if not isinstance(c["call_id"], str):
            raise ValueError("call_id must be a string")
        if not isinstance(c["loss_without_call"], (int, float)):
            raise ValueError("loss_without_call must be a number")
        if not isinstance(c["loss_with_call"], (int, float)):
            raise ValueError("loss_with_call must be a number")
        if not isinstance(c["prediction_tokens"], (int, float)) or c["prediction_tokens"] <= 0:
            raise ValueError("prediction_tokens must be positive number")
        if not isinstance(c["parseable"], bool):
            raise ValueError("parseable must be a boolean")
    # Process
    accepted_call_ids = []
    diagnostics = []
    for c in calls:
        gain = c["loss_without_call"] - c["loss_with_call"]
        normalized_gain = gain / c["prediction_tokens"]
        accepted = c["parseable"] and normalized_gain >= threshold
        if accepted:
            accepted_call_ids.append(c["call_id"])
        diagnostics.append({
            "accepted": accepted,
            "call_id": c["call_id"],
            "normalized_gain": normalized_gain
        })
    return {
        "accepted_call_ids": accepted_call_ids,
        "diagnostics": diagnostics
    }"}
